def newton(grad, hess, x, iters=20):
    for _ in range(iters):
        x = x - np.linalg.solve(hess(x), grad(x))
    return x

def backtrack(f, grad, x, d, a=1.0, c1=1e-4, rho=0.5):
    fx = f(x); gd = grad(x) @ d
    while f(x + a*d) > fx + c1*a*gd:
        a *= rho
    return a

