import math, random
def anneal(f, x, neighbor, T=1.0, alpha=0.95, steps=10000):
    for _ in range(steps):
        y = neighbor(x); d = f(y) - f(x)
        if d < 0 or random.random() < math.exp(-d/T):
            x = y
        T *= alpha
    return x

